sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float depth;
uniform float angle;
layout(color) uniform half4 sideColor;
layout(color) uniform half4 farColor;
uniform float shading;
uniform float faceBrightness;
uniform float opacity;
float4 texT(float2 p) {
    return float4(image.eval(p));
}
half4 fin(float4 o, float4 r, float op) {
    return half4(mix(o, r, saturate(op)));
}
half4 main(float2 coord) {
    float4 c = texT(coord);
    float2 dir = float2(cos(radians(angle)), sin(radians(angle)));
    float4 acc = float4(0.0);
    for (int i = 0; i < 24; i++) {
        float t = 1.0 - float(i) / 23.0;
        float a = texT(coord - dir * depth * t).a;
        float3 col = mix(float3(sideColor.rgb), float3(farColor.rgb), t) * mix(1.0, 1.0 - shading, t);
        float4 layer = float4(col * a, a);
        acc = layer + acc * (1.0 - layer.a);
    }
    float4 face = float4(c.rgb * faceBrightness, c.a);
    return fin(c, face + acc * (1.0 - face.a), opacity);
}
